import { useState } from "react";

export default function App() {
  const[counter, setCounter] = useState(0); //default Wert 0 -> muss den richtigen Datentyp haben
  console.log("Rerender");
 
  return (
    <div className="App">
      <div>Hallo Mond</div>
      <div>{counter}</div>
      <button onClick = {() => setCounter(counter + 1)}>Drück mich +1</button> //mit jedem Klick erhöht sich der Counter
      <button onClick = {() => setCounter(0)}>Drück mich 0</button>
    </div>
  );
}
